import type { RamayanaBeginningPlayableScene } from "./ramayana-beginnings-playable";

export const RAMAYANA_VALI_FALLS_PLAYABLE_SCENES: RamayanaBeginningPlayableScene[] = [
  { id: "tara-reads-the-second-roar", nodeIds: ["tara", "vali", "sugriva", "angada", "rama", "lakshmana", "kishkindha"], moment: { id: "tara-reads-the-second-roar", decisiveChange: { en: "Tara turns a repeated challenge into new intelligence, but Vali lets public pride outrank evidence and reconciliation.", hi: "तारा दोहराई चुनौती को नई सूचना में बदलती हैं, पर वाली प्रमाण और मेल से ऊपर सार्वजनिक अभिमान रखता है।" }, beats: [
    { id: "tara-hears-what-changed", title: { en: "The same voice now carries different confidence", hi: "वही आवाज़ अब अलग आत्मविश्वास लाती है" }, narration: { en: "Tara notices that Sugriva was beaten only moments earlier yet has returned with a stronger roar. She reasons that he would not challenge again without tested support. Her warning is not mystical foreknowledge: it compares two encounters, detects a changed condition, and asks Vali to delay until the new risk is understood.", hi: "तारा देखती हैं कि अभी-अभी पराजित सुग्रीव अधिक दृढ़ गर्जना के साथ लौटा है। वे तर्क करती हैं कि परखी सहायता के बिना वह फिर चुनौती नहीं देता। उनकी चेतावनी रहस्यमय भविष्यवाणी नहीं—दो मुठभेड़ों की तुलना, बदली परिस्थिति की पहचान और जोखिम समझने तक रुकने की माँग है।" }, visualCue: "The two challenge waves overlay across Kishkindha, making the second visibly stronger and revealing Tara's inference through comparison rather than exposition.", characterIds: ["tara", "sugriva", "vali"] },
    { id: "angadas-intelligence-has-a-source", title: { en: "Angada brings news gathered through the forest", hi: "अंगद वन से जुटी सूचना लाता है" }, narration: { en: "Tara says Angada heard from travelling emissaries that Rama and Lakshmana, princes of Ayodhya, now support Sugriva. Information moves through a living network rather than appearing because the plot needs it. Tara identifies Rama's reputation and military capacity as a material change Vali must include in his decision.", hi: "तारा बताती हैं कि अंगद ने घूमते दूतों से सुना—अयोध्या के राजकुमार राम और लक्ष्मण अब सुग्रीव के साथ हैं। सूचना कथानक की सुविधा से नहीं, जीवित नेटवर्क से चलती है। तारा राम की प्रतिष्ठा और युद्ध-शक्ति को ऐसा वास्तविक बदलाव मानती हैं जिसे वाली को निर्णय में शामिल करना चाहिए।" }, visualCue: "A messenger route runs from forest scouts through Angada to Tara, preserving who learned what before the information reaches Vali's chamber.", characterIds: ["angada", "tara", "rama", "lakshmana", "sugriva", "vali"] },
    { id: "tara-offers-a-road-without-battle", title: { en: "Reconciliation still has concrete terms", hi: "मेल के पास अभी भी ठोस शर्तें हैं" }, narration: { en: "Tara proposes restoring Sugriva as heir, honouring him, ending the feud, and making peace with Rama. The alternative is not a vague request to be kind. It redistributes status, acknowledges the younger brother, and converts dangerous outside support into a negotiated alliance before blood is shed.", hi: "तारा सुग्रीव को युवराज बनाने, सम्मान लौटाने, वैर समाप्त करने और राम से मैत्री का प्रस्ताव देती हैं। विकल्प केवल ‘दयालु बनो’ नहीं है। वह पद बाँटता, छोटे भाई को स्वीकारता और रक्त बहने से पहले बाहरी शक्तिशाली समर्थन को बातचीत की मैत्री में बदलता है।" }, visualCue: "A non-combat route opens from the chamber toward shared rule and a Rama-Sugriva-Vali council, remaining visibly available while Vali chooses.", characterIds: ["tara", "vali", "sugriva", "rama", "angada"] },
    { id: "anger-closes-the-counsel-route", title: { en: "Vali treats delay as humiliation", hi: "वाली रुकने को अपमान मानता है" }, narration: { en: "Vali hears the warning but experiences Sugriva's roar before his household as an insult no undefeated warrior can tolerate. Tara's careful comparison, Angada's intelligence, and the offer of reconciliation do not satisfy him. He leaves only after information and a concrete alternative have been placed before him.", hi: "वाली चेतावनी सुनता है, पर परिवार के सामने सुग्रीव की गर्जना को ऐसा अपमान मानता है जिसे अजेय योद्धा सह नहीं सकता। तारा की सावधान तुलना, अंगद की सूचना और मेल का प्रस्ताव उसे संतुष्ट नहीं करते। वह सूचना और ठोस विकल्प सामने रखे जाने के बाद ही निकलता है।" }, visualCue: "The reconciliation path dims only after Vali dismisses it; Tara's evidence remains pinned to the decision so her counsel cannot disappear from the later aftermath.", characterIds: ["vali", "tara", "sugriva", "angada", "rama"] },
  ] } },
  { id: "vali-enters-fight-and-arrow-falls", nodeIds: ["vali", "tara", "sugriva", "rama", "lakshmana", "kishkindha-gate", "forest-battle-ground", "gaja-flower-marker"], moment: { id: "vali-enters-fight-and-arrow-falls", decisiveChange: { en: "Vali leaves after promising restraint, the corrected duel identifies Sugriva, and Rama fulfils the lethal promise from concealment.", hi: "वाली संयम का वचन देकर निकलता है, सुधरा द्वंद्व सुग्रीव की पहचान कराता और राम छिपकर घातक वचन पूरा करते हैं।" }, beats: [
    { id: "vali-promises-less-than-death", title: { en: "Vali says he will defeat, not kill, his brother", hi: "वाली भाई को हराने, न मारने की बात कहता है" }, narration: { en: "Vali tells Tara that Rama should not act unjustly and promises only to crush Sugriva's pride, not take his life. Tara circles him, gives a tearful benediction, and returns inside. His assurance matters later: he walks out confident both in his own reading of Rama and in his ability to control the duel's limit.", hi: "वाली तारा से कहता है कि राम अन्याय नहीं करेंगे और वह सुग्रीव का अभिमान तोड़ेगा, प्राण नहीं लेगा। तारा आँसुओं के साथ परिक्रमा और मंगल-कामना कर भीतर लौटती हैं। यह आश्वासन आगे महत्वपूर्ण है—वह राम की अपनी समझ और द्वंद्व की सीमा नियंत्रित करने के विश्वास के साथ निकलता है।" }, visualCue: "Tara's blessing and Vali's stated restraint remain attached to him as active memory markers when he crosses from the inner chamber to the gate.", characterIds: ["vali", "tara", "rama", "sugriva"] },
    { id: "brothers-close-with-no-distance", title: { en: "The duel becomes body against body", hi: "द्वंद्व शरीर से शरीर का संघर्ष बनता है" }, narration: { en: "Vali and Sugriva tighten their clothing, close their fists, trade threats, and strike with hands, knees, branches, rocks, and trees. The fight is not an abstract health bar: two brothers with shared strength and history search for each other's weaknesses at close range while the marked flower garland distinguishes Sugriva from outside.", hi: "वाली और सुग्रीव वस्त्र कसते, मुट्ठियाँ बाँधते, ललकारते और हाथ, घुटने, डाल, पत्थर तथा वृक्ष से वार करते हैं। युद्ध केवल स्वास्थ्य-पट्टी नहीं—साझी शक्ति और इतिहास वाले दो भाई निकट से कमजोरी खोजते हैं, जबकि बाहर से पुष्प-चिह्न सुग्रीव को अलग पहचानता है।" }, visualCue: "The camera moves between the crushing close combat and Rama's distant sightline, where the flower marker now remains readable through every overlap.", characterIds: ["vali", "sugriva", "rama", "lakshmana"] },
    { id: "sugriva-spends-the-last-strength", title: { en: "Sugriva weakens and invokes the corrected plan", hi: "सुग्रीव कमजोर होकर सुधरी योजना का संकेत देता है" }, narration: { en: "Vali begins to prevail. Sugriva loses strength, suffers blows, and points out his opponent to Rama. Unlike the first challenge, the ally in danger now has both an agreed signal and a visible identity. Rama watches the deterioration and turns from observation to the arrow promised at Rishyamuka.", hi: "वाली बढ़त लेता है। सुग्रीव की शक्ति घटती, प्रहार लगते और वह राम को प्रतिद्वंद्वी दिखाता है। पहली चुनौती के विपरीत, संकट में साथी के पास तय संकेत और स्पष्ट पहचान दोनों हैं। राम उसकी गिरती हालत देखकर निरीक्षण से ऋष्यमूक पर वचन दिए बाण की ओर बढ़ते हैं।" }, visualCue: "Sugriva's signal, flower marker, and falling strength converge in Rama's view, documenting the exact moment the support condition is considered met.", characterIds: ["sugriva", "vali", "rama", "lakshmana"] },
    { id: "the-hidden-arrow-strikes", title: { en: "Rama releases from outside the duel", hi: "राम द्वंद्व के बाहर से बाण छोड़ते हैं" }, narration: { en: "Rama draws a blazing shaft from concealment and strikes Vali in the chest. Animals scatter at the bowstring; Vali falls bloodied and senseless while the brothers' combat stops. The distance and surprise do not disappear when the arrow lands, because Vali will awaken and make the unseen attack the centre of his challenge.", hi: "राम ओट से प्रज्वलित बाण खींचकर वाली की छाती में मारते हैं। प्रत्यंचा से पशु भागते, वाली रक्तरंजित और अचेत गिरता और भाइयों का युद्ध रुक जाता है। बाण लगते ही दूरी और आश्चर्य गायब नहीं होते, क्योंकि वाली चेतकर इसी अदृश्य प्रहार को अपने प्रश्न का केंद्र बनाएगा।" }, visualCue: "One uninterrupted trajectory runs from Rama's concealed bow to Vali's chest, then holds both firing position and fallen body in the same navigable space.", characterIds: ["rama", "vali", "sugriva", "lakshmana"] },
  ] } },
  { id: "vali-puts-rama-on-trial", nodeIds: ["vali", "rama", "lakshmana", "sugriva", "tara", "sita", "ravana", "forest-battle-ground"], moment: { id: "vali-puts-rama-on-trial", decisiveChange: { en: "The defeated opponent remains a speaking moral agent and turns the promised rescue into a public demand for justification.", hi: "पराजित प्रतिद्वंद्वी बोलता नैतिक पक्ष बना रहता है और वचनबद्ध सहायता को सार्वजनिक औचित्य की माँग में बदल देता है।" }, beats: [
    { id: "vali-speaks-before-anyone-celebrates", title: { en: "The fallen king is alive and demands an answer", hi: "गिरा राजा जीवित है और उत्तर माँगता है" }, narration: { en: "Rama and Lakshmana approach Vali, who lies wounded but still possesses voice and presence. He does not begin by asking for mercy. He asks what merit Rama gained by killing someone engaged with another opponent. The narrative interrupts any immediate celebration and gives the person struck first control of the ethical frame.", hi: "राम और लक्ष्मण घायल पर अभी बोलने और उपस्थिति रखने वाले वाली के पास आते हैं। वह दया नहीं माँगता; पूछता है कि दूसरे से लड़ते व्यक्ति को मारकर राम ने कौन-सा पुण्य पाया। कथा तत्काल उत्सव रोकती और प्रहार झेलने वाले को नैतिक प्रश्न की पहली आवाज़ देती है।" }, visualCue: "Victory prompts remain disabled as Vali's dialogue opens from ground level, forcing the player camera to meet his gaze rather than stand over a defeated icon.", characterIds: ["vali", "rama", "lakshmana", "sugriva"] },
    { id: "the-hidden-shot-is-the-charge", title: { en: "Vali challenges the method, not only the outcome", hi: "वाली परिणाम ही नहीं, तरीके पर प्रश्न करता है" }, narration: { en: "Vali says he trusted Rama's reputation for truth, discipline, compassion, and royal conduct, and therefore did not expect an unseen attack while fighting Sugriva. He asks why a prince claiming righteousness used lethal force without open warning or combat. The charge makes reputation itself evidence against the method chosen.", hi: "वाली कहता है कि उसने राम की सत्य, संयम, करुणा और राजधर्म वाली प्रतिष्ठा पर भरोसा किया, इसलिए सुग्रीव से लड़ते समय अदृश्य प्रहार की आशा नहीं की। वह पूछता है कि धर्म का दावा करने वाले राजकुमार ने खुली चेतावनी या युद्ध बिना घातक बल क्यों प्रयोग किया। प्रतिष्ठा ही चुने तरीके के विरुद्ध प्रमाण बनती है।" }, visualCue: "Rama's celebrated virtue markers appear beside the concealed firing line, letting Vali connect stated ideals to the action without the interface resolving the contradiction.", characterIds: ["vali", "rama", "sugriva", "tara"] },
    { id: "jurisdiction-and-injury-are-disputed", title: { en: "Vali asks what authority and injury connected them", hi: "वाली पूछता है कि कौन-सा अधिकार और अपराध उन्हें जोड़ता था" }, narration: { en: "Vali argues that he neither invaded Rama's city nor harmed him directly, and questions why human royal power should reach a forest-dwelling vanara in a fraternal dispute. He challenges the categories by which he has been hunted and punished, asking what land, wealth, injury, or declared war made him Rama's target.", hi: "वाली तर्क देता है कि उसने न राम के नगर पर चढ़ाई की, न उन्हें सीधे हानि पहुँचाई, और पूछता है कि भाइयों के विवाद में मानव राजसत्ता वनवासी वानर तक क्यों पहुँचे। वह उन श्रेणियों को चुनौती देता है जिनसे उसका आखेट और दंड हुआ—कौन-सी भूमि, संपत्ति, चोट या घोषित युद्ध ने उसे राम का लक्ष्य बनाया?" }, visualCue: "Contested jurisdiction rings overlap forest, Kishkindha, and the claimed Ikshvaku realm while direct-harm links to Rama remain visibly absent.", characterIds: ["vali", "rama", "sugriva", "lakshmana"] },
    { id: "vali-names-the-lost-alternative", title: { en: "He says he could have searched for Sita", hi: "वह कहता है कि सीता की खोज कर सकता था" }, narration: { en: "Vali says that, if Rama had stated his need, he could have brought Sita back and seized Ravana. Whether that boast was feasible cannot now be tested, but it exposes a road never attempted: negotiation before killing. Accepting Sugriva's succession, Vali still asks what answer Rama will give when others question the death.", hi: "वाली कहता है कि राम आवश्यकता बताते तो वह सीता को ला और रावण को पकड़ सकता था। यह दावा संभव था या नहीं, अब जाँचा नहीं जा सकता, पर हत्या से पहले बातचीत की अनआजमाई राह दिखाता है। सुग्रीव का उत्तराधिकार स्वीकारकर भी वह पूछता है कि मृत्यु पर प्रश्न होने पर राम क्या उत्तर देंगे।" }, visualCue: "A ghost route from Vali toward Sita and Ravana appears as permanently untested, distinct from completed events and from Vali's own claim of capability.", characterIds: ["vali", "rama", "sita", "ravana", "sugriva"] },
  ] } },
  { id: "rama-answers-and-angada-emerges", nodeIds: ["rama", "vali", "sugriva", "angada", "tara", "bharata", "ruma", "forest-battle-ground"], moment: { id: "rama-answers-and-angada-emerges", decisiveChange: { en: "Rama presents his justification; Vali accepts the reply and uses his remaining voice to secure duties toward the living.", hi: "राम अपना औचित्य रखते हैं; वाली उत्तर स्वीकारकर बची आवाज़ जीवित लोगों के प्रति दायित्व सुरक्षित करने में लगाता है।" }, beats: [
    { id: "rama-claims-royal-reach", title: { en: "Rama answers from a theory of royal jurisdiction", hi: "राम राजकीय अधिकार के सिद्धांत से उत्तर देते हैं" }, narration: { en: "Rama says the wider forested land lies under Ikshvaku rule administered by Bharata, and that rulers and their agents must reward or punish conduct across humans, animals, and birds. He presents that royal reach as the authority under which he travels, judges, and acts even while personally living in exile.", hi: "राम कहते हैं कि विस्तृत वनभूमि भरत द्वारा संचालित इक्ष्वाकु शासन के अधीन है और शासक तथा उनके प्रतिनिधि मनुष्य, पशु और पक्षियों के आचरण पर दंड-अनुग्रह कर सकते हैं। वे इसी राजकीय पहुँच को वह अधिकार बताते हैं जिसके अंतर्गत वनवास में रहते हुए भी वे यात्रा, निर्णय और कार्रवाई करते हैं।" }, visualCue: "An Ikshvaku jurisdiction layer expands over the forest labelled as Rama's asserted basis, while Vali's disputed boundary remains available for comparison.", characterIds: ["rama", "vali", "bharata", "sugriva"] },
    { id: "ruma-and-the-promise-form-the-case", title: { en: "The core accusation is taking the younger brother's wife", hi: "मुख्य आरोप छोटे भाई की पत्नी को अपने अधीन करना है" }, narration: { en: "Rama argues that Vali violated the familial duty to treat a younger brother like a son by taking Ruma, and says punishment also fulfils the friendship promise made publicly to restore Sugriva's wife and kingdom. The response joins an alleged wrong with an obligation already accepted; neither the kinship rule nor promise is hidden.", hi: "राम तर्क देते हैं कि छोटे भाई को पुत्रवत मानने का धर्म तोड़कर वाली ने रूमा को अपने अधीन किया, और दंड सुग्रीव की पत्नी तथा राज्य लौटाने के सार्वजनिक मैत्री-वचन को भी पूरा करता है। उत्तर कथित अपराध और पहले स्वीकृत दायित्व जोड़ता है; न संबंध-नियम छिपता है, न वचन।" }, visualCue: "Ruma's removed household link and the fire-witnessed promise appear as Rama's two central evidence paths, separate from the method-of-attack dispute.", characterIds: ["rama", "vali", "ruma", "sugriva"] },
    { id: "the-hunting-analogy-remains-contestable", title: { en: "A second defence compares the shot with hunting", hi: "दूसरा बचाव प्रहार की तुलना आखेट से करता है" }, narration: { en: "Rama adds that hunters and royal ascetics strike forest animals openly or from ambush and therefore says Vali could be hit whether fighting him or not. The comparison does not answer Vali's own account of himself as king, brother, husband, and possible ally; it stands as one disputed part of Rama's wider defence.", hi: "राम आगे कहते हैं कि शिकारी और राजर्षि वन्य जीवों को सामने या ओट से मारते हैं, इसलिए वाली को उनसे लड़ते या न लड़ते प्रहार किया जा सकता था। तुलना वाली के अपने राजा, भाई, पति और संभावित साथी होने के वर्णन का उत्तर नहीं देती; वह राम के व्यापक बचाव का एक विवादित भाग बनी रहती है।" }, visualCue: "The hunting analogy appears in a separately bordered argument card with an explicit contested-state treatment, never replacing Vali's speaking character node.", characterIds: ["rama", "vali"] },
    { id: "angada-becomes-the-living-obligation", title: { en: "Vali redirects the argument toward his son", hi: "वाली बहस को अपने पुत्र की ओर मोड़ता है" }, narration: { en: "Vali accepts Rama's reply and asks forgiveness for his accusations, but his deepest concern is Angada, young and dependent on Tara. He asks Rama to ensure Sugriva protects both. Rama promises that he and Sugriva will raise Angada with the care Vali gave him, turning justification into a future duty.", hi: "वाली राम का उत्तर स्वीकारकर आरोपों के लिए क्षमा माँगता है, पर उसकी सबसे बड़ी चिंता तारा पर निर्भर युवा अंगद है। वह राम से सुग्रीव द्वारा दोनों की रक्षा सुनिश्चित करने को कहता है। राम वचन देते हैं कि वे और सुग्रीव अंगद को वाली जैसी देखभाल देंगे—औचित्य भविष्य का दायित्व बनता है।" }, visualCue: "The debate does not close with a verdict stamp; it transfers into durable protection links from Rama and Sugriva toward Angada and Tara.", characterIds: ["vali", "rama", "angada", "tara", "sugriva"] },
  ] } },
  { id: "tara-crosses-the-fleeing-city", nodeIds: ["tara", "angada", "vali", "rama", "sugriva", "kishkindha", "forest-battle-ground", "kishkindha-vanaras"], moment: { id: "tara-crosses-the-fleeing-city", decisiveChange: { en: "News of Vali's fall fractures Kishkindha into flight, defence, succession, and grief, while Tara refuses to let political urgency decide her first response.", hi: "वाली के गिरने का समाचार किष्किंधा को पलायन, रक्षा, उत्तराधिकार और शोक में बाँट देता है, जबकि तारा राजनीतिक तात्कालिकता को अपनी पहली प्रतिक्रिया तय नहीं करने देतीं।" }, beats: [
    { id: "news-reaches-the-inner-cave", title: { en: "The battle enters Tara's world as a report", hi: "युद्ध तारा की दुनिया में समाचार बनकर आता है" }, narration: { en: "Tara hears that Rama's arrow has struck Vali and leaves the inner mountain with Angada. She encounters followers already fleeing at the sight of Rama's bow. The king's fall travels faster than any settled account of what follows, so fear begins reorganising the city before Vali's condition or succession has been collectively faced.", hi: "तारा सुनती हैं कि राम का बाण वाली को लगा और अंगद के साथ भीतरी पर्वत से निकलती हैं। उन्हें राम का धनुष देखकर भागते अनुयायी मिलते हैं। राजा के गिरने की खबर आगे की किसी स्थिर योजना से तेज चलती है, इसलिए वाली की स्थिति या उत्तराधिकार का सामूहिक सामना होने से पहले भय नगर को पुनर्गठित करने लगता है।" }, visualCue: "A spreading alarm wave moves from battlefield to inner chambers and city gates, showing routes closing before any formal command is issued.", characterIds: ["tara", "angada", "vali", "rama", "kishkindha-vanaras"] },
    { id: "fleeing-vanaras-see-a-power-vacuum", title: { en: "The first responders fear invasion and retaliation", hi: "पहले उत्तरदाता आक्रमण और प्रतिशोध से डरते हैं" }, narration: { en: "The vanaras urge Tara to return, secure the stronghold, and install Angada before rivals exploit the vacuum. Their advice reveals households, lost wealth, and old enmities inside Vali's kingdom. The city is not one cheering population awaiting a new ruler; different groups calculate safety as royal protection disappears.", hi: "वानर तारा से लौटकर दुर्ग सुरक्षित करने और प्रतिद्वंद्वी शून्य का लाभ लें उससे पहले अंगद को स्थापित करने को कहते हैं। उनकी बात वाली के राज्य के भीतर परिवार, खोया धन और पुराने वैर दिखाती है। नगर नया राजा चाहती एक जयकार करती भीड़ नहीं; राजकीय सुरक्षा हटते ही अलग समूह अपनी सुरक्षा गिनते हैं।" }, visualCue: "Competing defence, gate, treasury, and Angada-installation routes light around Kishkindha, each tagged to frightened speakers rather than treated as adopted policy.", characterIds: ["tara", "angada", "kishkindha-vanaras", "vali"] },
    { id: "tara-refuses-power-as-first-aid", title: { en: "Tara chooses Vali over immediate rule", hi: "तारा तत्काल शासन से पहले वाली को चुनती हैं" }, narration: { en: "Tara says that with Vali fallen, kingdom, son, and her own safety cannot be her first destination. She will go to him. This does not deny Angada's importance; it refuses to use his installation to bypass the human reality of the death. Political continuity must wait long enough for truth and grief to be encountered.", hi: "तारा कहती हैं कि वाली के गिरने पर राज्य, पुत्र और अपनी सुरक्षा उनकी पहली मंज़िल नहीं हो सकते; वे उसके पास जाएँगी। यह अंगद का महत्व नहीं नकारता, बल्कि उसकी स्थापना से मृत्यु की मानवीय सच्चाई को पार करने से इंकार है। राजनीतिक निरंतरता को सत्य और शोक से मिलने जितना रुकना होगा।" }, visualCue: "The throne route remains open behind Tara while she deliberately selects the battlefield path, carrying Angada without converting him into a crown icon.", characterIds: ["tara", "angada", "vali", "kishkindha-vanaras"] },
    { id: "tara-crosses-every-party", title: { en: "She passes the victors and reaches the fallen", hi: "वह विजयी पक्षों को पार कर गिरे हुए तक पहुँचती हैं" }, narration: { en: "Tara passes Rama, Lakshmana, and Sugriva and finds Vali on the ground. She loses consciousness, rises, and cries out; Angada and the gathered community join the grief. Sugriva, seeing the family before the body, is no longer able to experience the fulfilled promise only as liberation.", hi: "तारा राम, लक्ष्मण और सुग्रीव को पार कर भूमि पर पड़े वाली तक पहुँचती हैं। वे अचेत होकर उठती और पुकारती हैं; अंगद तथा समुदाय शोक में जुड़ते हैं। परिवार को शव के सामने देखकर सुग्रीव पूरा हुआ वचन केवल मुक्ति की तरह अनुभव नहीं कर सकता।" }, visualCue: "The camera follows Tara past each armed and political actor without interruption until it drops to Vali's level, where all victory-state effects fall silent.", characterIds: ["tara", "vali", "angada", "rama", "lakshmana", "sugriva"] },
  ] } },
  { id: "tara-laments-before-the-fallen-king", nodeIds: ["tara", "vali", "angada", "sugriva", "rama", "ruma", "forest-battle-ground", "kishkindha"], moment: { id: "tara-laments-before-the-fallen-king", decisiveChange: { en: "Tara's lament holds love, accusation, foresight, fear for Angada, and recognition of Vali's wrong together without simplifying any of them.", hi: "तारा का विलाप प्रेम, आरोप, दूरदृष्टि, अंगद की चिंता और वाली की भूल की पहचान को बिना सरल किए साथ रखता है।" }, beats: [
    { id: "tara-speaks-to-silence", title: { en: "She addresses husband and king as if response were still possible", hi: "वह पति और राजा से ऐसे बोलती हैं जैसे उत्तर अभी संभव हो" }, narration: { en: "Tara embraces Vali and asks why he does not welcome her, why a king lies on bare earth, and why their shared forest life has ended without farewell. She recalls fragrant groves, private happiness, and the authority with which he once answered every gathering. None of those memories can make the silent body respond.", hi: "तारा वाली को गले लगाकर पूछती हैं कि वह स्वागत क्यों नहीं करता, राजा नंगी धरती पर क्यों पड़ा है और उनका साझा वन-जीवन बिना विदाई क्यों समाप्त हुआ। वे सुगंधित उपवन, निजी सुख और हर सभा को उत्तर देने वाली उसकी सत्ता याद करती हैं। कोई स्मृति मौन शरीर से उत्तर नहीं दिला सकती।" }, visualCue: "Memories of shared groves appear only around Tara's spoken details, while Vali's unresponsive body anchors every image to the present loss.", characterIds: ["tara", "vali"] },
    { id: "love-does-not-erase-causation", title: { en: "Tara names the wrong and the ignored warning", hi: "तारा भूल और अनसुनी चेतावनी दोनों कहती हैं" }, narration: { en: "Tara says Vali's seizure of Sugriva's wife and exile led to this result, and that he ignored counsel intended for his welfare. She also condemns Rama's timing and method. Grief does not force her into one loyal simplification: she can love Vali, recognise his responsibility, and still challenge the act that killed him.", hi: "तारा कहती हैं कि सुग्रीव की पत्नी को अपने अधीन करना और उसे निकालना इस परिणाम तक लाया, और वाली ने हित की सलाह नहीं सुनी। वे राम के समय और तरीके की भी निंदा करती हैं। शोक उन्हें एक सरल निष्ठा में नहीं बाँधता—वह वाली से प्रेम, उसकी जिम्मेदारी की पहचान और हत्या पर प्रश्न साथ रखती हैं।" }, visualCue: "Three distinct causal threads—Vali's conduct, rejected counsel, and Rama's shot—remain visible together without merging into a single blame score.", characterIds: ["tara", "vali", "sugriva", "ruma", "rama"] },
    { id: "angadas-future-enters-the-lament", title: { en: "A child must face a court transformed by his father's death", hi: "पिता की मृत्यु से बदले दरबार का सामना पुत्र को करना है" }, narration: { en: "Tara calls Angada to look one last time and asks how his angry uncle will treat a young heir raised in privilege. She asks Vali to bless and instruct the son who can no longer receive either. Angada's future is not a later governance checkbox; it enters the grief at the instant paternal protection disappears.", hi: "तारा अंगद को अंतिम बार देखने बुलाती और पूछती हैं कि क्रोधित चाचा सुख में पले युवा उत्तराधिकारी से कैसा व्यवहार करेगा। वे वाली से उस पुत्र को आशीष और निर्देश माँगती हैं जो अब दोनों नहीं पा सकता। अंगद का भविष्य बाद का शासन-चेकबॉक्स नहीं; पिता की सुरक्षा मिटते ही शोक में प्रवेश करता है।" }, visualCue: "Angada's character route branches toward family, court, and Sugriva while every path begins at the unanswered gesture toward his father.", characterIds: ["tara", "angada", "vali", "sugriva"] },
    { id: "no-one-receives-a-clean-victory", title: { en: "Tara confronts Sugriva and Rama with the cost", hi: "तारा सुग्रीव और राम को मूल्य के सामने खड़ा करती हैं" }, narration: { en: "Tara tells Sugriva that he may regain Ruma and rule without fear, but speaks those gains beside the brother's body. She asks why Rama does not relent after the hidden shot and resolves to remain with Vali. Her words make the achieved objective inseparable from the household and community it has broken.", hi: "तारा सुग्रीव से कहती हैं कि वह रूमा को पाकर निर्भय राज्य कर सकता है, पर ये लाभ भाई के शव के पास कहती हैं। वे पूछती हैं कि छिपे प्रहार के बाद राम क्यों नहीं पिघलते और वाली के पास रहने का निश्चय करती हैं। उनकी वाणी प्राप्त लक्ष्य को टूटे परिवार और समुदाय से अलग नहीं होने देती।" }, visualCue: "Restored-wife and restored-kingdom markers appear beside the mourning circle, refusing to animate as rewards while their human cost remains unresolved.", characterIds: ["tara", "sugriva", "rama", "vali", "ruma", "angada"] },
  ] } },
  { id: "hanuman-offers-duty-tara-refuses-throne", nodeIds: ["hanuman", "tara", "angada", "sugriva", "vali", "forest-battle-ground", "kishkindha-throne", "vali-funeral"], moment: { id: "hanuman-offers-duty-tara-refuses-throne", decisiveChange: { en: "Hanuman names the duties that cannot wait forever, while Tara prevents grief from being converted immediately into a claim she does not believe is hers.", hi: "हनुमान वे दायित्व बताते हैं जो सदा नहीं रुक सकते, जबकि तारा शोक को तुरंत ऐसे दावे में बदलने से रोकती हैं जिसे वह अपना नहीं मानतीं।" }, beats: [
    { id: "hanuman-consoles-from-his-worldview", title: { en: "Hanuman answers grief with impermanence and action", hi: "हनुमान अनित्यता और कर्म से शोक का उत्तर देते हैं" }, narration: { en: "Hanuman tells Tara that embodied life is unstable and actions bear consequences, urging her to turn toward what remains. His words do not make her loss smaller or end the mourning around Vali. They introduce a different pressure: Angada, the community, and the unperformed rites still depend on decisions from the living.", hi: "हनुमान तारा से कहते हैं कि देहधारी जीवन अस्थिर है और कर्म फल देते हैं, इसलिए जो बचा है उसकी ओर मुड़ें। उनकी वाणी हानि छोटी नहीं करती, न वाली के आसपास का शोक समाप्त। वह दूसरी आवश्यकता सामने लाती है—अंगद, समुदाय और बाकी संस्कार अब भी जीवितों के निर्णय पर निर्भर हैं।" }, visualCue: "Hanuman's counsel appears as attributable dialogue beside, not over, Tara's grief state, with no wellness instruction or universal maxim extracted from it.", characterIds: ["hanuman", "tara", "vali"] },
    { id: "angada-and-rites-cannot-wait-forever", title: { en: "Care, funeral, and continuity require decisions", hi: "देखभाल, अंत्येष्टि और निरंतरता को निर्णय चाहिए" }, narration: { en: "Hanuman points to Angada, the waiting community, Vali's funeral rites, and the vacant rule. He proposes that Angada perform a son's ceremonies and be installed. These are distinct needs—care for a young person, honour for the dead, and political stability—not one argument that a crown will cure sorrow.", hi: "हनुमान अंगद, प्रतीक्षारत समुदाय, वाली की अंत्येष्टि और खाली शासन की ओर संकेत करते हैं। वे अंगद से पुत्र-कर्म और उसके राज्यारोहण का प्रस्ताव रखते हैं। ये अलग आवश्यकताएँ हैं—युवा की देखभाल, मृत का सम्मान और राजनीतिक स्थिरता—यह दावा नहीं कि मुकुट शोक ठीक कर देगा।" }, visualCue: "Four separate pending routes open for Angada care, funeral rites, community safety, and succession, preventing governance from swallowing every other obligation.", characterIds: ["hanuman", "tara", "angada", "vali", "sugriva"] },
    { id: "tara-refuses-an-authority-she-does-not-claim", title: { en: "Tara says succession belongs with Sugriva", hi: "तारा कहती हैं कि उत्तराधिकार सुग्रीव के पास है" }, narration: { en: "Tara says she cannot govern or confer the kingdom on Angada and that the authority now falls to his uncle Sugriva. Her refusal is political judgment, not lack of intelligence—the previous scene has already established her as the clearest strategist. She will not use emergency grief to manufacture a legitimacy she does not accept.", hi: "तारा कहती हैं कि वह न शासन कर सकती हैं, न अंगद को राज्य दे सकतीं; अधिकार अब उसके चाचा सुग्रीव के पास है। यह राजनीतिक निर्णय है, बुद्धि का अभाव नहीं—पहला दृश्य उन्हें सबसे स्पष्ट रणनीतिक आवाज़ बना चुका है। वे आपात शोक से ऐसी वैधता नहीं गढ़ेंगी जिसे नहीं मानतीं।" }, visualCue: "The proposed Tara-to-Angada crown transfer closes by her choice, while a separate counsel node preserves her strategic authority for the future court.", characterIds: ["tara", "angada", "sugriva", "hanuman"] },
    { id: "grief-cannot-yet-be-instrumentalised", title: { en: "Tara remains with Vali before accepting a public role", hi: "तारा सार्वजनिक भूमिका से पहले वाली के पास रहती हैं" }, narration: { en: "Tara says that neither many sons nor a kingdom can replace the husband before her and chooses to remain at his side. She cannot yet imagine public duty as a reason to leave him. Hanuman's proposals remain unanswered, leaving Angada, Sugriva, and the surrounding community responsible for care until she can choose again.", hi: "तारा कहती हैं कि अनेक पुत्र या राज्य सामने पड़े पति का स्थान नहीं ले सकते और उसके पास रहने को चुनती हैं। वह अभी सार्वजनिक कर्तव्य को उससे दूर जाने का कारण नहीं मान सकतीं। हनुमान के प्रस्ताव अनुत्तरित रहते हैं, इसलिए अंगद, सुग्रीव और समुदाय पर देखभाल की जिम्मेदारी रहती है जब तक वह फिर चुनाव कर सकें।" }, visualCue: "Tara's proximity to Vali is held without unlocking any self-harm action; care characters and future pathways remain present around her.", characterIds: ["tara", "vali", "hanuman", "angada", "sugriva"] },
  ] } },
  { id: "vali-entrusts-angada-and-dies", nodeIds: ["vali", "sugriva", "angada", "tara", "golden-garland", "forest-battle-ground", "kishkindha"], moment: { id: "vali-entrusts-angada-and-dies", decisiveChange: { en: "Vali's last authority becomes an explicit transfer of care, counsel, symbol, and survival strategy before the relationship can no longer be repaired by speech.", hi: "वाली की अंतिम सत्ता देखभाल, सलाह, प्रतीक और जीवित रहने की रणनीति का स्पष्ट हस्तांतरण बनती है, फिर संबंध वाणी से सुधर नहीं सकता।" }, beats: [
    { id: "vali-apologises-to-sugriva", title: { en: "The brothers speak after hostility has lost its future", hi: "भाई तब बोलते हैं जब वैर का भविष्य समाप्त हो चुका है" }, narration: { en: "Vali calls Sugriva close and asks him not to carry the elder brother's wrongful conduct forever. He says fate did not allow them to hold kingdom and fraternal affection together. The apology does not undo exile, seizure, fear, or death; it creates a final acknowledgment from the person who caused much of that harm.", hi: "वाली सुग्रीव को पास बुलाकर कहता है कि बड़े भाई के अनुचित आचरण को सदा हृदय में न रखे। वह मानता है कि भाग्य ने उन्हें राज्य और भाईचारा साथ नहीं दिया। क्षमा निर्वासन, हरण, भय या मृत्यु नहीं मिटाती; वह बहुत हानि करने वाले व्यक्ति की अंतिम स्वीकारोक्ति बनती है।" }, visualCue: "The hostility edge between the brothers changes to acknowledged harm rather than disappearing, preserving both apology and irreversibility.", characterIds: ["vali", "sugriva"] },
    { id: "angada-is-entrusted-as-a-son", title: { en: "Sugriva receives a parental obligation", hi: "सुग्रीव को पिता जैसा दायित्व मिलता है" }, narration: { en: "Vali asks Sugriva to maintain Angada as his own son, satisfy his needs, remove fear, and recognise his future courage in the search against the rakshasas. This is not only a succession request. It binds the new ruler to protect the child whose position his victory has made most dangerous.", hi: "वाली सुग्रीव से अंगद को अपने पुत्र की तरह पालने, आवश्यकताएँ पूरी करने, भय हटाने और राक्षसों के विरुद्ध उसकी भविष्य की वीरता पहचानने को कहता है। यह केवल उत्तराधिकार निवेदन नहीं; नई सत्ता को उस बच्चे की रक्षा से बाँधता है जिसकी स्थिति विजय ने सबसे जोखिमपूर्ण बनाई।" }, visualCue: "A durable guardian link forms from Sugriva to Angada with care, safety, and future-service facets, distinct from the heirship link added later.", characterIds: ["vali", "sugriva", "angada"] },
    { id: "tara-and-the-garland-transfer", title: { en: "Counsel and royal fortune are handed onward", hi: "सलाह और राजलक्ष्मी आगे सौंपी जाती हैं" }, narration: { en: "Vali tells Sugriva to trust Tara's judgment in danger because her counsel does not fail, and to honour the obligation owed to Rama. He then gives Sugriva the golden garland associated with his vitality and royal fortune. The transfer recognises Tara as continuing intelligence, not merely a widow attached to the former reign.", hi: "वाली सुग्रीव से संकट में तारा की बुद्धि पर भरोसा करने को कहता है क्योंकि उनकी सलाह निष्फल नहीं, और राम का दायित्व निभाने को भी कहता है। फिर वह अपनी जीवन-शक्ति और राजलक्ष्मी से जुड़ी स्वर्णमाला देता है। हस्तांतरण तारा को केवल पूर्व राजा की विधवा नहीं, जारी बुद्धि मानता है।" }, visualCue: "The golden garland moves to Sugriva while a separate counsel route stays anchored on Tara, preventing symbolic kingship from absorbing her authority.", characterIds: ["vali", "sugriva", "tara", "rama"] },
    { id: "angada-hears-how-to-survive-the-new-court", title: { en: "A father's last advice is adaptation, not entitlement", hi: "पिता की अंतिम सीख अधिकार नहीं, अनुकूलन है" }, narration: { en: "Vali tells Angada to accept Sugriva's authority, read time and place, endure hardship, avoid both excessive intimacy and hostile distance, and serve the new order carefully. Then he dies and the community cries out. The counsel reveals how uncertain the young heir's safety remains even after public promises of protection.", hi: "वाली अंगद से सुग्रीव का अधिकार मानने, समय-स्थान समझने, कठिनाई सहने, न अत्यधिक निकटता न शत्रुतापूर्ण दूरी रखने और नई व्यवस्था सावधानी से निभाने को कहता है। फिर वह मरता और समुदाय रोता है। सीख दिखाती है कि सार्वजनिक सुरक्षा-वचनों के बाद भी युवा उत्तराधिकारी की स्थिति कितनी अनिश्चित है।" }, visualCue: "Angada receives a balanced-path navigation rule between dangerous closeness and isolation; the lesson persists when Vali's character light goes out.", characterIds: ["vali", "angada", "sugriva", "tara"] },
  ] } },
  { id: "tara-and-angada-say-goodbye", nodeIds: ["tara", "angada", "vali", "nila", "rama", "sugriva", "forest-battle-ground", "rama-arrow"], moment: { id: "tara-and-angada-say-goodbye", decisiveChange: { en: "The household moves from speaking toward Vali's possible response to caring for a body that can no longer bless, explain, or return.", hi: "परिवार वाली के संभावित उत्तर से बोलने की अवस्था से उस शरीर की देखभाल की ओर बढ़ता है जो अब आशीष, स्पष्टीकरण या वापसी नहीं दे सकता।" }, beats: [
    { id: "tara-keeps-addressing-vali", title: { en: "Words continue after the last breath", hi: "अंतिम साँस के बाद भी शब्द चलते हैं" }, narration: { en: "Tara smells Vali's face and asks why he lies on rough ground after rejecting her counsel. She speaks of widowhood, broken honour, the community's cries, and the battle-bed where his former enemies once lay. Her lament changes as death becomes certain, but relationship still structures every observation.", hi: "तारा वाली का मुख सूँघकर पूछती हैं कि उनकी सलाह ठुकराने के बाद वह कठोर भूमि पर क्यों पड़ा है। वे विधवापन, टूटे सम्मान, समुदाय के रोने और उस रण-शय्या की बात करती हैं जहाँ कभी उसके शत्रु पड़े थे। मृत्यु निश्चित होते ही विलाप बदलता है, पर हर अवलोकन संबंध से बना है।" }, visualCue: "Tara's spoken memories map directly onto ground, city, community, and former battles while Vali's node remains present but no longer interactive.", characterIds: ["tara", "vali", "angada"] },
    { id: "nila-removes-the-arrow", title: { en: "The weapon is removed from the body", hi: "शरीर से बाण निकाला जाता है" }, narration: { en: "Tara says the arrow prevents her from embracing Vali. Nila draws it out, and blood flows from the wound. The act is physical care and evidence handling, not spectacle. Rama's weapon remains identifiable after removal, preserving the connection between distant shot, ethical dispute, bodily injury, and funeral preparation.", hi: "तारा कहती हैं कि बाण उन्हें वाली को गले लगाने से रोकता है। नील उसे निकालता और घाव से रक्त बहता है। यह शारीरिक देखभाल और प्रमाण-संभाल है, तमाशा नहीं। निकला हुआ राम का अस्त्र पहचान योग्य रहता है, जिससे दूर का प्रहार, नैतिक बहस, देह की चोट और अंत्येष्टि-तैयारी जुड़े रहते हैं।" }, visualCue: "The camera stays with Nila's careful extraction; the arrow moves to a separate evidence position while the wound is treated without graphic emphasis.", characterIds: ["nila", "tara", "vali", "rama"] },
    { id: "tara-cleans-what-war-left", title: { en: "Tears and touch replace combat motion", hi: "युद्ध की गति की जगह आँसू और स्पर्श लेते हैं" }, narration: { en: "Tara washes dust and blood from Vali with her tears and calls Angada to see the end of his father's conflict. Care work changes the battlefield's function: a place built for strikes becomes one where family prepares the dead for farewell. Weapons lower, bodies gather, and the cost of violence becomes the only movement left.", hi: "तारा आँसुओं से वाली के शरीर की धूल और रक्त साफ करतीं और अंगद को पिता के वैर का अंत देखने बुलाती हैं। देखभाल रणभूमि का काम बदल देती है—वार की जगह परिवार मृतक को विदाई के लिए तैयार करता है। शस्त्र झुकते, लोग पास आते और हिंसा का मूल्य ही बची हुई गति बनता है।" }, visualCue: "Combat affordances disappear as Tara's care reveals the same body beneath dust and blood; nearby characters lower weapons and form a mourning circle.", characterIds: ["tara", "vali", "angada", "nila"] },
    { id: "angada-bows-without-a-blessing", title: { en: "The son touches feet that cannot answer", hi: "पुत्र उन चरणों में झुकता है जो उत्तर नहीं दे सकते" }, narration: { en: "Angada embraces Vali's feet, but the familiar blessing does not come. Tara names that silence and notices the royal garland is gone, already transferred to Sugriva. The child encounters two absences at once: his father's voice and the symbol of rule that once made their household the centre of Kishkindha.", hi: "अंगद वाली के चरण पकड़ता है, पर परिचित आशीर्वाद नहीं आता। तारा उस मौन को कहतीं और देखती हैं कि राजमाला जा चुकी है, सुग्रीव को सौंप दी गई। पुत्र एक साथ दो अनुपस्थितियों से मिलता है—पिता की आवाज़ और वह शासन-चिह्न जिसने उनके घर को किष्किंधा का केंद्र बनाया था।" }, visualCue: "Angada's bow waits for a response that never triggers; the missing garland route points toward Sugriva without pulling the camera away from the child.", characterIds: ["angada", "vali", "tara", "sugriva"] },
  ] } },
  { id: "victory-turns-to-remorse", nodeIds: ["sugriva", "tara", "rama", "angada", "vali", "rishyamuka", "kishkindha-throne", "forest-battle-ground"], moment: { id: "victory-turns-to-remorse", decisiveChange: { en: "The beneficiary of Vali's death rejects simple triumph, and two expressions of self-destructive grief force Rama to answer what obligations remain toward the living.", hi: "वाली की मृत्यु से लाभ पाने वाला सरल विजय ठुकराता है, और आत्म-विनाश की दो शोक-इच्छाएँ राम को जीवितों के प्रति बचे दायित्वों का उत्तर देने को मजबूर करती हैं।" }, beats: [
    { id: "sugriva-cannot-enjoy-the-fulfilled-promise", title: { en: "The regained kingdom no longer feels like the desired object", hi: "लौटा राज्य अब चाही वस्तु जैसा नहीं लगता" }, narration: { en: "Sugriva approaches Rama and says the promise has been fulfilled, yet Tara, Angada, subjects, and the dead brother make enjoyment impossible. He recalls preferring bare survival at Rishyamuka to a kingdom purchased at this cost. Liberation from pursuit has arrived together with responsibility for the death that enabled it.", hi: "सुग्रीव राम के पास कहता है कि वचन पूरा हुआ, फिर भी तारा, अंगद, प्रजा और मृत भाई राज्य-सुख असंभव बनाते हैं। वह याद करता है कि इस मूल्य पर मिले राज्य से ऋष्यमूक का साधारण जीवन बेहतर था। पीछा से मुक्ति उसी मृत्यु की जिम्मेदारी के साथ आई है जिसने उसे संभव किया।" }, visualCue: "The throne reward remains locked while Sugriva's view connects it backward to every mourner and to the now-empty refuge where he once survived.", characterIds: ["sugriva", "rama", "tara", "angada", "vali"] },
    { id: "memory-complicates-sugrivas-blame", title: { en: "He remembers that Vali once spared him", hi: "उसे याद आता है कि वाली ने कभी उसे छोड़ दिया था" }, narration: { en: "Sugriva recalls Vali ending the first duel without killing him and now judges his own desire for death more harshly. His remorse may idealise the brother after loss, but it also records moral agency: he does not hide behind Rama's arrow or the earlier wrongs. He asks whether rule can be legitimate without facing his part.", hi: "सुग्रीव याद करता है कि पहली लड़ाई में वाली ने उसे जीवित छोड़ा और अब अपनी मृत्यु-कामना को अधिक कठोरता से देखता है। शोक भाई को आदर्श बना सकता है, फिर भी यह नैतिक जिम्मेदारी दर्ज करता है—वह राम के बाण या पुराने अपराधों के पीछे नहीं छिपता। वह पूछता है कि अपनी भूमिका का सामना बिना शासन वैध कैसे होगा।" }, visualCue: "The earlier spared-at-boundary memory replays beside the lethal second plan, giving Sugriva's remorse concrete events rather than a generic guilt effect.", characterIds: ["sugriva", "vali", "rama"] },
    { id: "despair-spreads-through-the-survivors", title: { en: "Sugriva and Tara both ask to leave life", hi: "सुग्रीव और तारा दोनों जीवन छोड़ने की बात कहते हैं" }, narration: { en: "Sugriva asks to enter fire, imagining the search can continue without him. Tara comes to Rama and asks to be killed by the same arrow so she can rejoin Vali. Rama does not grant either request. His tears and silence acknowledge that the promised victory has produced a crisis among the people who survived it.", hi: "सुग्रीव अग्नि में जाने की अनुमति माँगता, मानता है कि खोज उसके बिना चल सकती है। तारा राम से उसी बाण से मारकर वाली के पास भेजने को कहती हैं। राम किसी माँग को स्वीकार नहीं करते। उनके आँसू और मौन मानते हैं कि वचन की विजय ने बचे लोगों के बीच गहरा संकट बनाया है।" }, visualCue: "No self-harm interaction is enabled; care routes converge on Sugriva and Tara while the search path visibly shows why their continued lives matter.", characterIds: ["sugriva", "tara", "rama", "vali", "angada"] },
    { id: "rama-points-to-angadas-living-future", title: { en: "The answer is protection and a future role", hi: "उत्तर सुरक्षा और भविष्य की भूमिका है" }, narration: { en: "Rama refuses Tara's request and says Angada will become heir, asking her not to lose herself. His language invokes divine ordering and heroic endurance from the source, but the actionable commitment is earthly: keep Tara alive, protect Angada, and create a political future in which the child is not erased by his uncle's victory.", hi: "राम तारा की माँग अस्वीकारकर कहते हैं कि अंगद युवराज होगा और उनसे स्वयं को न खोने को कहते हैं। स्रोत की भाषा दैवी व्यवस्था और वीर-सहनशीलता लेती है, पर क्रियात्मक वचन सांसारिक है—तारा को जीवित रखना, अंगद की रक्षा और ऐसा राजनीतिक भविष्य बनाना जिसमें चाचा की विजय पुत्र को न मिटाए।" }, visualCue: "A future heirship route opens from Angada but passes through Tara's continued care and Sugriva's guardianship, not directly from grief to crown.", characterIds: ["rama", "tara", "angada", "sugriva"] },
  ] } },
  { id: "kishkindha-carries-vali-to-fire", nodeIds: ["vali", "tara", "angada", "sugriva", "rama", "lakshmana", "kishkindha-community", "hill-stream-cremation-ground", "river"], moment: { id: "kishkindha-carries-vali-to-fire", decisiveChange: { en: "Private collapse becomes coordinated public farewell, giving Angada, Tara, Sugriva, and the wider community distinct places in Vali's final rites.", hi: "निजी टूटन समन्वित सार्वजनिक विदाई बनती है, जिसमें अंगद, तारा, सुग्रीव और व्यापक समुदाय को वाली के अंतिम संस्कार में अलग स्थान मिलता है।" }, beats: [
    { id: "time-for-rites-is-spoken-not-assumed", title: { en: "Rama redirects lament toward appointed action", hi: "राम विलाप को नियत कर्म की ओर मोड़ते हैं" }, narration: { en: "Rama tells Tara, Angada, and Sugriva that tears have expressed worldly grief and funeral duties should no longer be delayed. He speaks of Time and the consequences of prior action, then returns to the immediate responsibility before them: Vali's body and the gathered mourners now need organised care.", hi: "राम तारा, अंगद और सुग्रीव से कहते हैं कि आँसू सांसारिक शोक व्यक्त कर चुके और अंत्येष्टि अब नहीं टलनी चाहिए। वे काल और पूर्वकर्म के परिणाम की बात कर फिर सामने की जिम्मेदारी पर लौटते हैं—वाली की देह और जुटे शोकाकुलों को अब संगठित देखभाल चाहिए।" }, visualCue: "Rama's worldview remains attributable dialogue while a practical funeral task map opens separately for materials, people, route, fire, and water.", characterIds: ["rama", "tara", "angada", "sugriva", "vali"] },
    { id: "lakshmana-organises-the-work", title: { en: "Grief receives materials, roles, and sequence", hi: "शोक को सामग्री, भूमिकाएँ और क्रम मिलता है" }, narration: { en: "Lakshmana asks Sugriva to gather dry wood and sandal, Angada to bring cloth, garlands, scents, ghee, and oil, Tara to obtain the bier, and strong vanaras to carry it. Naming roles prevents ritual from becoming decorative montage. Each mourner has work proportionate to relationship and capacity.", hi: "लक्ष्मण सुग्रीव से सूखी लकड़ी और चंदन, अंगद से वस्त्र, माला, सुगंध, घी और तेल, तारा से अर्थी और समर्थ वानरों से उसे उठाने को कहते हैं। भूमिकाएँ संस्कार को सजावटी दृश्य बनने से रोकती हैं। हर शोकाकुल को संबंध और क्षमता के अनुरूप काम मिलता है।" }, visualCue: "A shared preparation space lets materials arrive from different characters, with no single hero completing the funeral through one interaction.", characterIds: ["lakshmana", "sugriva", "angada", "tara", "kishkindha-community"] },
    { id: "the-city-walks-behind-its-king", title: { en: "The bier turns mourning into a public procession", hi: "अर्थी शोक को सार्वजनिक यात्रा बनाती है" }, narration: { en: "Vali is placed on an ornamented, flower-covered conveyance. Vanaras scatter royal gifts ahead; counsellors, subjects, Tara, Angada, Sugriva, and the other women follow through hills and forest. Tara keeps speaking to Vali from the bier. The kingdom does not switch rulers in private while its former king disappears off-screen.", hi: "वाली को अलंकृत, पुष्पों से ढकी अर्थी पर रखा जाता है। आगे वानर राजकीय दान बिखेरते; पीछे मंत्री, प्रजा, तारा, अंगद, सुग्रीव और अन्य स्त्रियाँ पहाड़-वन से चलती हैं। तारा अर्थी पर वाली से बोलती रहती हैं। राज्य निजी रूप से राजा बदलकर पुराने राजा को पर्दे के बाहर गायब नहीं करता।" }, visualCue: "The player can walk inside the slow procession as city, forest, and hill echo the lament, preserving community scale without turning grief into spectacle.", characterIds: ["vali", "tara", "angada", "sugriva", "kishkindha-community"] },
    { id: "angada-lights-and-community-offers-water", title: { en: "The son completes fire; the community completes water", hi: "पुत्र अग्नि देता; समुदाय जलांजलि पूरी करता है" }, narration: { en: "At a waterside clearing, Angada and Sugriva place Vali on the pyre. Angada lights it and circles his father; afterward the mourners go to the river and offer water with Angada in front. Rama and Lakshmana remain participants in the sorrow, but the family and Kishkindha community perform the central acts.", hi: "जल के पास खुले स्थान पर अंगद और सुग्रीव वाली को चिता पर रखते हैं। अंगद अग्नि देकर पिता की परिक्रमा करता; फिर शोकाकुल नदी जाकर अंगद को आगे रख जलांजलि देते हैं। राम-लक्ष्मण शोक में सहभागी हैं, पर मुख्य कर्म परिवार और किष्किंधा समुदाय करते हैं।" }, visualCue: "Control passes from Angada at the fire to the gathered community at the river, ending with shared water rather than a triumph or coronation cut.", characterIds: ["angada", "vali", "sugriva", "tara", "rama", "lakshmana", "kishkindha-community"] },
  ] } },
  { id: "crown-and-heir-under-rains", nodeIds: ["sugriva", "angada", "rama", "lakshmana", "hanuman", "ruma", "tara", "kishkindha-palace", "mountain-cave", "monsoon"], moment: { id: "crown-and-heir-under-rains", decisiveChange: { en: "Succession restores rule without erasing exile constraints or the search debt: Sugriva becomes king, Angada becomes heir, and the monsoon postpones—not cancels—the alliance's work.", hi: "उत्तराधिकार निर्वासन-सीमा या खोज-दायित्व मिटाए बिना शासन लौटाता है—सुग्रीव राजा, अंगद युवराज बनते और वर्षा मैत्री का काम रद्द नहीं, स्थगित करती है।" }, beats: [
    { id: "rama-keeps-the-exile-boundary", title: { en: "Rama will direct the transition but not enter the city", hi: "राम परिवर्तन निर्देशित करेंगे, नगर में प्रवेश नहीं" }, narration: { en: "Hanuman invites Rama to enter Kishkindha and preside over Sugriva's installation. Rama refuses because his father's fourteen-year command bars him from towns and cities. Helping one ruler take power does not suspend the vow governing his own conduct. He remains outside in a mountain cave with Lakshmana.", hi: "हनुमान राम को किष्किंधा आकर सुग्रीव के राज्यारोहण का नेतृत्व करने बुलाते हैं। राम मना करते हैं क्योंकि पिता की चौदह-वर्षीय आज्ञा उन्हें नगरों से दूर रखती है। एक शासक को सत्ता दिलाना अपने आचरण वाला वचन निलंबित नहीं करता। वे लक्ष्मण के साथ बाहर पर्वत-गुफा में रहते हैं।" }, visualCue: "The city gate opens for Sugriva's party while an explicit vow boundary keeps Rama and Lakshmana on the mountain side without severing communication routes.", characterIds: ["hanuman", "rama", "lakshmana", "sugriva"] },
    { id: "king-and-heir-are-installed-together", title: { en: "Succession includes Angada in the new order", hi: "नई व्यवस्था में अंगद भी स्थापित होता है" }, narration: { en: "Rama instructs Sugriva to install Angada as heir because Vali's eldest son is worthy. Inside Kishkindha, the community welcomes Sugriva, gathers ritual water and regalia, and installs him; Sugriva then embraces Angada and confers the heirship. Victory does not make Vali's line politically disappear.", hi: "राम सुग्रीव से वाली के योग्य ज्येष्ठ पुत्र अंगद को युवराज बनाने कहते हैं। किष्किंधा में समुदाय सुग्रीव का स्वागत कर अभिषेक-जल और राजचिह्न जुटाकर उन्हें स्थापित करता; फिर सुग्रीव अंगद को गले लगाकर युवराज पद देता है। विजय वाली की वंश-रेखा को राजनीतिक रूप से गायब नहीं करती।" }, visualCue: "Two linked installations activate king and heir nodes in sequence, with Angada's route visibly preserving continuity across the broken household.", characterIds: ["rama", "sugriva", "angada", "tara", "kishkindha-community"] },
    { id: "monsoon-closes-the-search-roads", title: { en: "Season limits movement without ending urgency", hi: "ऋतु मार्ग रोकती है, तात्कालिकता नहीं" }, narration: { en: "The month of Shravana begins the four rainy months. Rama says this is not the time for a physical search and plans to remain in the mountain cave until Kartika. The pause is deterministic season and terrain logic, not loss of interest in Sita. A dated obligation to resume is attached to the alliance.", hi: "श्रावण से चार वर्षा-मास शुरू होते हैं। राम कहते हैं कि भौतिक खोज का समय नहीं और कार्तिक तक पर्वत-गुफा में रहेंगे। विराम ऋतु और भू-मार्ग का निश्चित तर्क है, सीता में रुचि का अंत नहीं। मैत्री के साथ फिर शुरू करने का समयबद्ध दायित्व जुड़ता है।" }, visualCue: "Rain visibly floods and obscures outbound routes while a Kartika resume marker remains fixed on the search map instead of allowing the quest to vanish.", characterIds: ["rama", "lakshmana", "sugriva", "sita"] },
    { id: "restoration-creates-the-next-debt", title: { en: "Sugriva regains kingdom and Ruma, then owes action", hi: "सुग्रीव राज्य और रूमा पाकर अब कार्रवाई का ऋणी है" }, narration: { en: "Sugriva is crowned, Ruma returns to his household, friends celebrate, and the city raises flags. These restorations complete his side of the original exchange but do not complete the alliance. After the rains he must organise the search and confront Ravana's reach; the next turn will test whether power remembers the promise that enabled it.", hi: "सुग्रीव का राज्यारोहण होता, रूमा घर लौटतीं, मित्र उत्सव करते और नगर ध्वज उठाता है। ये वापसी मूल विनिमय में उसके पक्ष को पूरा करती हैं, मैत्री को नहीं। वर्षा बाद उसे खोज संगठित कर रावण की पहुँच का सामना करना है; अगला मोड़ जाँचेगा कि सत्ता उस वचन को याद रखती है जिसने उसे संभव बनाया।" }, visualCue: "Celebration remains inside Kishkindha while an unfulfilled promise line runs outward to Rama's cave and Sita's unknown location, preventing a false completion state.", characterIds: ["sugriva", "ruma", "rama", "sita", "angada", "hanuman"] },
  ] } },
];
